<?php declare(strict_types=1); use FastWebsite\Core\View; require __DIR__ . '/show.php'; ?>
<section class="admin-panel metadata-panel" id="themes"><div class="panel-heading"><div><p class="eyebrow">Research discovery</p><h2>Research themes</h2></div><a class="button button-secondary button-compact" href="<?=View::escape($baseUrl)?>admin/research/metadata">Manage catalogue</a></div><?php if ($themes === []): ?><p class="admin-empty compact">No themes assigned.</p><?php else: ?><div class="metadata-chip-grid"><?php foreach ($themes as $theme): ?><span class="metadata-chip"><?=View::escape($theme['name'])?><?php if ($canManageThemes): ?><form method="post" action="<?=View::escape($baseUrl)?>admin/research/publications/<?=(int)$publication['id']?>/themes/<?=(int)$theme['id']?>/remove"><input type="hidden" name="_token" value="<?=View::escape($csrfToken)?>"><button type="submit" aria-label="Remove <?=View::escape($theme['name'])?>">×</button></form><?php endif; ?></span><?php endforeach; ?></div><?php endif; ?><?php if ($canManageThemes && $themeOptions !== []): ?><form class="compact-assignment-form" method="post" action="<?=View::escape($baseUrl)?>admin/research/publications/<?=(int)$publication['id']?>/themes"><input type="hidden" name="_token" value="<?=View::escape($csrfToken)?>"><select name="theme_id" required><option value="">Choose published theme</option><?php foreach ($themeOptions as $theme): ?><option value="<?=(int)$theme['id']?>"><?=View::escape($theme['name'])?></option><?php endforeach; ?></select><button class="button button-primary button-compact" type="submit">Assign theme</button></form><?php endif; ?></section>
